GRADES = ('VERBATIM', 'VARIANT', 'TURNED', 'SHORTENED', 'EXPANDED', 'SUPPLIED', 'DISAGREES')
def rb(verses, told, grade, why, tape_kind=None, tape_verse=None, cell=None, cell_found=None, entry='', open_=False, write=None, state=False, pointer=None):
    assert grade in GRADES, grade
    if grade == 'SUPPLIED':
        assert tape_kind is None and cell is None, ("a SUPPLIED row references no line and no cell", verses)
        assert (isinstance(write, str) and write and not state) or (write is None and state), ("a SUPPLIED row is a STATE row (no write) or a law's first seat WITH its write", verses)
    else:
        assert (tape_kind is None) != (cell is None) and write is None and not state, ('one of the tape or the cell; no write on a reference row', verses)
        if cell is not None: assert cell_found is True, ('the kin cell CALLED and found', verses, cell)
